import test from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import type { LearningPreparation } from "./learning";
import { episodeStartLabel, readEpisodeBriefing } from "./episode-briefing";

// The fixture is generated by server.learning.preparation_response from an
// approved learning-v1 catalog. It deliberately contains no scenario roster.
const fixture = JSON.parse(
  readFileSync(
    new URL(
      "./fixtures/episode-briefing/public-preparation-v1.json",
      import.meta.url,
    ),
    "utf8",
  ),
) as LearningPreparation;
const fresh = () => structuredClone(fixture);

test("a public server-frozen lesson reaches the client exactly without mutating its context or preparation", () => {
  const preparation = fresh(),
    original = structuredClone(preparation);
  const b = readEpisodeBriefing(preparation);
  assert.ok(b);
  assert.equal(b.catalog_hash, preparation.context.catalog_hash);
  assert.equal(b.item_id, preparation.context.item_id);
  assert.equal(b.preparation_id, preparation.preparation_id);
  assert.equal(b.scenario_id, preparation.scenario.id);
  assert.match(b.objective, /contact/i);
  assert.ok(b.instructions.length);
  assert.equal(episodeStartLabel(b), "Start Academy practice");
  assert.notEqual(b, preparation.briefing);
  assert.notEqual(b.instructions, preparation.briefing!.instructions);
  assert.ok(Object.isFrozen(b));
  assert.ok(Object.isFrozen(b.instructions));
  assert.deepEqual(preparation, original);
  assert.throws(() => {
    (b.instructions as string[]).push("mutated");
  });
});
test("absent briefing and previous preparations remain compatible and never substitute current catalog prose", () => {
  const old = fresh();
  delete old.briefing;
  assert.equal(readEpisodeBriefing(old), null);
  assert.equal(readEpisodeBriefing({ ...old, briefing: null }), null);
  assert.equal(readEpisodeBriefing(null), null);
  assert.equal(readEpisodeBriefing(undefined), null);
});
test("scope, frozen catalog, mode, assistance and version mismatches fail closed", () => {
  const corruptions: ((p: LearningPreparation) => void)[] = [
    (p) => {
      p.preparation_id = "another-preparation";
    },
    (p) => {
      p.scenario.id = "another-scenario";
    },
    (p) => {
      p.context.catalog_hash = "0".repeat(64);
    },
    (p) => {
      p.context.item_id = "C02_PRACTICE_A";
    },
    (p) => {
      p.context.mode = "assessment";
    },
    (p) => {
      p.context.assistance = "faded";
    },
    (p) => {
      (p.context as { version: string }).version = "learning-v2";
    },
    (p) => {
      (p.briefing as unknown as { version: string }).version =
        "episode-briefing-v2";
    },
    (p) => {
      (p.briefing as unknown as { catalog_version: string }).catalog_version =
        "learning-v2";
    },
  ];
  for (const corrupt of corruptions) {
    const p = fresh();
    corrupt(p);
    assert.equal(readEpisodeBriefing(p), null);
  }
});
test("public field whitelist and bounded readable prose reject hidden data, malformed arrays and coercible objects", () => {
  const bad: Record<string, unknown>[] = [
    { mix: ["hostile_quad"] },
    { title: " " },
    { objective: "x".repeat(1001) },
    { instructions: [] },
    { instructions: [null] },
    { instructions: Array(2) },
    { instructions: Array(13).fill("instruction") },
    { instructions: ["x".repeat(1001)] },
    { competency_id: "C06" },
    { catalog_hash: "A".repeat(64) },
    {
      catalog_hash: {
        toString() {
          throw new Error("Do not coerce untrusted objects");
        },
      },
    },
  ];
  for (const fields of bad) {
    const p = fresh();
    p.briefing = { ...p.briefing!, ...fields };
    assert.equal(readEpisodeBriefing(p), null);
  }
  const p = fresh();
  delete (p.briefing as unknown as Record<string, unknown>).objective;
  assert.equal(readEpisodeBriefing(p), null);
});
test("independent assessment is explicitly labeled and cannot inherit guided practice assistance", () => {
  const p = fresh();
  p.context.mode = "assessment";
  p.context.assistance = "none";
  p.briefing = { ...p.briefing!, mode: "assessment", assistance: "none" };
  const b = readEpisodeBriefing(p);
  assert.ok(b);
  assert.equal(episodeStartLabel(b), "Start independent assessment");
  p.briefing = { ...p.briefing!, assistance: "full" };
  assert.equal(readEpisodeBriefing(p), null);
  p.context.mode = "adaptive";
  p.context.assistance = "faded";
  p.briefing = { ...p.briefing!, mode: "adaptive", assistance: "faded" };
  assert.equal(
    episodeStartLabel(readEpisodeBriefing(p)!),
    "Start adaptive practice",
  );
});

test("a valid previous lesson never supplies prose to a different live scenario", () => {
  const p = fresh();
  assert.ok(readEpisodeBriefing(p, p.scenario.id));
  assert.equal(readEpisodeBriefing(p, "another-live-scenario"), null);
  assert.equal(readEpisodeBriefing(p, ""), null);
  assert.equal(
    readEpisodeBriefing(p, p.scenario.id)!.item_id,
    p.context.item_id,
  );
});
